// Fontes Playfair Display embutidas como data URI (base64) — evita depender do
// empacotamento de assets estaticos da function serverless (Vercel/nft): o
// react-pdf le `src` como data URL inteiramente em memoria (sem tocar fs),
// entao a fonte sempre vai junto do bundle da function, garantido.
const PLAYFAIR_REGULAR = 'data:font/ttf;base64,';
const PLAYFAIR_SEMIBOLD = 'data:font/ttf;base64,';

module.exports = { PLAYFAIR_REGULAR, PLAYFAIR_SEMIBOLD };
